import { init, log, trace } from "neatlogs";

export const telemetryReady = init({
  workflowName: "nlhack",
  apiKey: process.env.NEATLOGS_API_KEY,
  captureLogs: true,
  debug: process.env.NEATLOGS_DEBUG === "true",
  ...(process.env.NEATLOGS_ENDPOINT ? { endpoint: process.env.NEATLOGS_ENDPOINT } : {}),
});

if (!process.env.NEATLOGS_API_KEY) {
  console.warn("NEATLOGS_API_KEY is missing: traces will not be exported to the dashboard.");
}

export async function traceRequest<T>(
  channel: "cli",
  sessionId: string,
  run: () => Promise<T>,
  input?: unknown,
): Promise<T> {
  await telemetryReady;
  return trace({
    name: `${channel}.request`,
    kind: "WORKFLOW",
    sessionId,
    sessionEntryPoint: channel,
    input,
    attributes: { "app.channel": channel },
  }, async (activeSpan) => {
    console.info("Neatlogs trace started", { channel, traceId: activeSpan.spanContext().traceId, sessionId });
    log("Request started", { channel });
    try {
      const result = await run();
      log("Request completed", { channel });
      return result;
    } catch (error) {
      log("Request failed", { channel, level: "error", error: error instanceof Error ? error.message : String(error) });
      throw error;
    }
  });
}
import { resolve } from "node:path";
import { Mastra } from "@mastra/core/mastra";
import { LibSQLStore } from "@mastra/libsql";
import { dataDir } from "../data-dir";
import "../telemetry";
import { assistant } from "./agents/assistant";
import { marketResearcher } from "./agents/market-researcher";
import { cfoAgent } from "./agents/cfo";
import { githubAgent } from "./agents/github";
import { neatlogsAgent } from "./agents/neatlogs";
import { customerSuccessAgent } from "./agents/customer-success";
import { legalAgent } from "./agents/legal";
import { hrAgent } from "./agents/hr";
import { marketingAgent } from "./agents/marketing";
import { salesAgent } from "./agents/sales";
import { workspace } from "./workspace";

export const mastra = new Mastra({
  storage: new LibSQLStore({ id: "mastra", url: `file:${resolve(dataDir(), "mastra.db")}` }),
  // Every agent (including sub-agents the Assistant delegates to) inherits the per-user file workspace.
  workspace,
  agents: { assistant, marketResearcher, cfoAgent, customerSuccessAgent, legalAgent, hrAgent, marketingAgent, salesAgent, githubAgent, neatlogsAgent },
});
import { Agent } from "@mastra/core/agent";
import { memory } from "../memory";
import { wrapMastra } from "neatlogs/mastra";
import { NEATLOGS_INSTRUCTIONS } from "../prompts";
import { getNeatlogsTools } from "../tools/neatlogs";

/**
 * Chatted with directly in the web app, and delegated to by the Assistant. Reads every agent's
 * Neatlogs traces and can change triage items and detections; each such call suspends for the
 * user's approval in whichever chat started it (see neatlogsToolNeedsApproval).
 */
export const neatlogsAgent = wrapMastra(new Agent({
  id: "neatlogs",
  name: "Neatlogs Agent",
  description:
    "Analyzes the Neatlogs traces of this project's agent runs: errors, latency, token usage, evaluations, detections, and triage items. Can update triage items and create detections; every change is shown with its exact arguments and runs only after you approve it.",
  instructions: NEATLOGS_INSTRUCTIONS,
  model: "deepseek/deepseek-flash",
  memory,
  // Resolved per request so a missing key or Neatlogs outage never blocks server startup.
  tools: () => getNeatlogsTools(),
  defaultOptions: { maxSteps: 12 },
}));
